css:
:scope { width: min(100%, 1128px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__i1 { grid-column: 14 / span 10; grid-row: 1 / span 19; font-family: var(--os-font-label); font-size: 129px; font-weight: 400; line-height: 0.5; letter-spacing: 0em; color: var(--os-color-background); }
.gx__i2 { grid-column: 5 / span 10; grid-row: 5 / span 5; font-family: var(--os-font-label); font-size: 74px; font-weight: 400; line-height: 0.5; letter-spacing: 0em; text-align: center; color: var(--os-color-background); }
.gx__i3 { grid-column: 1 / span 10; grid-row: 7 / span 59; aspect-ratio: 471 / 469; }
.gx__i4 { grid-column: 12 / span 10; grid-row: 21 / span 15; font-family: var(--os-font-body); font-size: 20px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; color: var(--os-color-background); }
.gx__i5 { grid-column: 12 / span 10; grid-row: 39 / span 18; font-family: var(--os-font-body); font-size: 20px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; color: var(--os-color-background); }
.gx__i6 { grid-column: 12 / span 10; grid-row: 58 / span 4; font-family: var(--os-font-body); font-size: 20px; font-weight: 400; line-height: 1.4; letter-spacing: 0em; color: var(--os-color-background); }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__i1 { font-family: var(--os-font-label); font-size: 103px; }
  .gx__i2 { font-family: var(--os-font-label); font-size: 59px; }
  .gx__i4 { font-family: var(--os-font-body); font-size: 16px; }
  .gx__i5 { font-family: var(--os-font-body); font-size: 16px; }
  .gx__i6 { font-family: var(--os-font-body); font-size: 16px; }
}
